from apps.core.monitoring import init_sentry

from .base import *  # noqa: F403
from .base import (
    SENTRY_DSN,
    SENTRY_RELEASE,
    SENTRY_TRACES_SAMPLE_RATE,
    STORAGES,
    env,
    env_bool,
)

DEBUG = False

# Keys that sign the sessions, the password reset and the email confirmation links: random and
# never one published in this repository (the defaults and examples of the other settings). 32
# characters at least: values generated by hosting platforms (Render's generateValue) can be
# shorter than the 50 that Django's deploy check suggests, and are random anyway.
MIN_KEY_LENGTH = 32
WEAK_KEY_MARKERS = ("insecure", "change-me", "changeme", "example")
WEAK_KEY_PREFIXES = ("dev-", "local-", "test-")


def weak_key(value: str) -> bool:
    lowered = value.lower()
    return (
        len(value) < MIN_KEY_LENGTH
        or len(set(value)) < 5
        or lowered.startswith(WEAK_KEY_PREFIXES)
        or any(marker in lowered for marker in WEAK_KEY_MARKERS)
    )


if not env("DJANGO_SECRET_KEY"):
    raise RuntimeError("DJANGO_SECRET_KEY must be set in production")
# JWT_SIGNING_KEY is optional (SECRET_KEY signs the tokens otherwise).
for _variable in ("DJANGO_SECRET_KEY", "JWT_SIGNING_KEY"):
    if env(_variable) and weak_key(env(_variable)):
        raise RuntimeError(
            f"{_variable} is too weak: use a long random value, e.g. "
            'python -c "import secrets; print(secrets.token_urlsafe(50))"'
        )

# Emails carry the password reset and email confirmation links: printing them in the logs (console
# backend) would let anyone who reads the logs take over the accounts.
EMAIL_BACKEND = env("EMAIL_BACKEND", "django.core.mail.backends.smtp.EmailBackend")
UNSENT_EMAIL_BACKENDS = ("console", "filebased", "locmem", "dummy")
if EMAIL_BACKEND.rsplit(".", 2)[-2] in UNSENT_EMAIL_BACKENDS and not env_bool(
    "ALLOW_CONSOLE_EMAIL"
):
    raise RuntimeError(
        f"EMAIL_BACKEND={EMAIL_BACKEND} does not send the emails (their links would end up in the "
        "logs). Configure SMTP, or set ALLOW_CONSOLE_EMAIL=1 for a test environment."
    )

STORAGES["staticfiles"] = {
    "BACKEND": "whitenoise.storage.CompressedManifestStaticFilesStorage",
}

# TLS terminates at Render's proxy, which sets X-Forwarded-Proto.
SECURE_PROXY_SSL_HEADER = ("HTTP_X_FORWARDED_PROTO", "https")
SECURE_SSL_REDIRECT = env_bool("SECURE_SSL_REDIRECT", True)
SECURE_HSTS_SECONDS = int(env("SECURE_HSTS_SECONDS", "31536000"))
SECURE_HSTS_INCLUDE_SUBDOMAINS = True
SECURE_HSTS_PRELOAD = True
SECURE_CONTENT_TYPE_NOSNIFF = True
SECURE_REFERRER_POLICY = "same-origin"
SESSION_COOKIE_SECURE = True
CSRF_COOKIE_SECURE = True
X_FRAME_OPTIONS = "DENY"

# No Django admin (brute-force target with access to health data) nor public API docs, unless
# explicitly turned on for a staging environment.
ADMIN_ENABLED = env_bool("ADMIN_ENABLED", False)
API_DOCS_PUBLIC = env_bool("API_DOCS_PUBLIC", False)

init_sentry(
    SENTRY_DSN,
    environment=env("SENTRY_ENVIRONMENT", "production"),
    release=SENTRY_RELEASE,
    traces_sample_rate=SENTRY_TRACES_SAMPLE_RATE,
)
